operations.after:
Scanner *scanner = (Scanner *)payload;

if (valid_symbols[FILE_BASED_APP_START] && scanner->quote_count == 0 &&
    scanner->interpolation_stack.size == 0) {
    bool line_start = lexer->get_column(lexer) == 0;
    while (iswspace(lexer->lookahead)) {
        if (lexer->lookahead == '\n' || lexer->lookahead == '\r') {
            line_start = true;
        }
        skip(lexer);
    }
    if (lexer->lookahead == '#') {
        if (!line_start) {
            return false;
        }
        advance(lexer);
        if (lexer->lookahead != ':') {
            return false;
        }
        advance(lexer);
        lexer->mark_end(lexer);
        lexer->result_symbol = FILE_BASED_APP_START;
        return true;
    }
    // Only whitespace was skipped; other handlers retain their original path.
}

